∀ {G : Type u_1} [inst : Group G] (n : ℕ),
  Submodule.toAddSubgroup (DirectedCycles.augmentationIdeal G ^ (n + 1)) =
    AddSubgroup.closure {x | ∃ gs, gs.length = n + 1 ∧ DirectedCycles.groupDifferenceWord gs = x}

∀ {G : Type u_1} [inst : Group G] [inst_1 : TopologicalSpace G] [IsTopologicalGroup G] {ι : Type u_2} {l : Filter ι}
  [l.NeBot] {A : ι → TopologicalSpace.Compacts G} {E : TopologicalSpace.Compacts G},
  Filter.Tendsto A l (nhds E) → ∀ {B : Set G}, IsClosed B → ∀ (n : ℕ), (∀ᶠ (i : ι) in l, ↑(A i) ^ n ⊆ B) → ↑E ^ n ⊆ B

∀ {G : Type u_1} [inst : Group G] [inst_1 : TopologicalSpace G] [IsTopologicalGroup G] {ι : Type u_2} {l : Filter ι}
  [l.NeBot] [T2Space G] {A : ι → TopologicalSpace.Compacts G} {E : TopologicalSpace.Compacts G},
  Filter.Tendsto A l (nhds E) → (∀ᶠ (i : ι) in l, (↑(A i))⁻¹ = ↑(A i)) → (↑E)⁻¹ = ↑E

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal) {E : Type u_1} [inst_1 : NormedAddCommGroup E]
  [inst_2 : NormedSpace ℝ E] [inst_3 : ChartedSpace E M.carrier] [LieGroup (modelWithCornersSelf ℝ E) (↑⊤) M.carrier],
  have this := DirectedCycles.openSubgroupChartedSpace (Subgroup.connectedComponentOfOne M.carrier) ⋯;
  LieGroup (modelWithCornersSelf ℝ E) (↑⊤) (DirectedCycles.connectedLieGoodModel M).carrier

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] [inst_1 : Fintype I] {D : DirectedCycles.Digraph I} {root : I}
  (B : DirectedCycles.PartialOutBranching D root Finset.univ) (S : I → I → Set G) (label : I → I → G),
  (∀ (x y : I), B.arc x y → label x y ∈ S x y) →
    have p := fun i => B.potential label i ⋯;
    p root = 1 ∧ ∀ (x y : I), B.arc x y → 1 ∈ DirectedCycles.gaugeLabels S p x y

∀ {α : Type u_1} {G : Type u_2} [inst : Group G] (x : α → G) (n : ℕ),
  DirectedCycles.iteratedGeneratorCommutators (Set.range x) n ⊆
    {z | ∃ w, w.weight = n + 1 ∧ DirectedCycles.CommutatorWord.eval x w = z}

∀ {G : Type u_1} [inst : Group G] [Finite G] {A : Set G} {r c : ℕ}
  (W : (DirectedCycles.LocalGroupAlgebra.ofGroup G).ProgressionWitness A r c) (a J : ℕ),
  a ≤ J * ∏ i, (2 * W.lengths i + 1) → ∃ P, P.carrier ⊆ A ∧ a ≤ J * Nat.card ↑P.carrier

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal),
  Nonempty (DirectedCycles.LieQuotientData M.carrier M.neighbourhood)

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal) (B : Set G) (V : Set M.carrier),
  IsOpen V → 1 ∈ V → ⇑M.map ⁻¹' V ⊆ B → ∃ F, T ⊆ ↑F * B

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal) (S : Subgroup M.carrier),
  IsOpen ↑S → ∃ F, T ⊆ ↑F * (T ∩ ↑(Subgroup.comap M.map S))

∀ {G : Type u_1} [inst : Group G] [inst_1 : MeasurableSpace G] (μ : MeasureTheory.Measure G) {f k : G → ℝ}
  {A B : Set G},
  (∀ x ∉ A, f x = 0) → (∀ x ∉ B, k x = 0) → ∀ {x : G}, x ∉ A * B → DirectedCycles.haarConvolution μ f k x = 0

∀ {G : Type u_1} {H : Type u_2} [inst : Group G] [inst_1 : Group H] (f : G →* H) {r c : ℕ}
  (P : DirectedCycles.CosetNilprogression G r c),
  (DirectedCycles.imageCosetNilprogression f P).carrier = ⇑f '' P.carrier

∀ {G : Type u_1} {V : Type u_2} [inst : Group G] [inst_1 : MulAction G V] (N L : Subgroup G) [inst_2 : L.Normal],
  L ≤ N →
    (∀ (x : V), N ⊓ MulAction.stabilizer G x ≤ L) →
      let A := DirectedCycles.PermutationImage G (Quotient (MulAction.orbitRel (↥L) V));
      have M := Subgroup.map (DirectedCycles.normalOrbitImageHom L) N;
      ∀ (g : ↥M) (q : Quotient (MulAction.orbitRel (↥L) V)), g • q = q → g = 1

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal) [TotallyDisconnectedSpace M.carrier],
  ∃ N, Internal ↑N ∧ ↑N ⊆ T ∧ ∃ F, T ⊆ ↑F * ↑N

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] [inst_1 : Fintype I] {D : DirectedCycles.Digraph I} {root : I}
  (A : DirectedCycles.PartialOutBranching (fun x y => D y x) root Finset.univ) (label : I → I → G),
  ∃ t, t root = 1 ∧ ∀ (x y : I), A.arc y x → t x = label x y * t y

∀ {α : Type u_1} {G : Type u_2} [inst : Group G] (g : α → G) (n : ℕ),
  DirectedCycles.iteratedGeneratorCommutators (Set.range g) n ⊆
    {x | ∃ i l, l.length = n ∧ DirectedCycles.leftGeneratorCommutator g i l = x}

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal)
  (D : DirectedCycles.LieQuotientData M.carrier M.neighbourhood),
  have this := D.charts;
  LieGroup (modelWithCornersSelf ℝ (EuclideanSpace ℝ (Fin D.dimension))) (↑⊤)
    (DirectedCycles.lieQuotientGoodModel M D).carrier

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal)
  (D : DirectedCycles.LieQuotientData M.carrier M.neighbourhood) (x : ↥(Subgroup.comap M.map D.source)),
  have this := ⋯;
  (DirectedCycles.lieQuotientGoodModel M D).map x =
    (QuotientGroup.mk' D.kernel) ((DirectedCycles.subgroupModelHom M.map D.source) x)

∀ {G : Type u_1} {E : Type u_2} [inst : Group G] [inst_1 : TopologicalSpace G] [inst_2 : NormedAddCommGroup E]
  [inst_3 : NormedSpace ℝ E] [inst_4 : ChartedSpace E G] [hLie : LieGroup (modelWithCornersSelf ℝ E) (↑⊤) G],
  have e := chartAt E 1;
  have c := ↑e 1;
  have χ := fun p => ↑e (↑e.symm (p.1 + c) * ↑e.symm (p.2 + c) * (↑e.symm (p.1 + c))⁻¹) - c;
  ContDiffAt ℝ (↑⊤) χ (0, 0) ∧ (∀ᶠ (x : E) in nhds 0, χ (x, 0) = 0) ∧ (fun y => χ (0, y)) =ᶠ[nhds 0] id

∀ {G : Type u_1} {E : Type u_2} [inst : Group G] [inst_1 : TopologicalSpace G] [inst_2 : NormedAddCommGroup E]
  [inst_3 : NormedSpace ℝ E] [inst_4 : ChartedSpace E G] [hLie : LieGroup (modelWithCornersSelf ℝ E) (↑⊤) G],
  have e := chartAt E 1;
  have c := ↑e 1;
  have μ := fun p => ↑e (↑e.symm (p.1 + c) * ↑e.symm (p.2 + c)) - c;
  ContDiffAt ℝ (↑⊤) μ (0, 0) ∧
    (fun x => μ (x, 0)) =ᶠ[nhds 0] id ∧
      (fun x => μ (0, x)) =ᶠ[nhds 0] id ∧
        ∀ᶠ (p : E × E) in nhds (0, 0), (fun z => μ (μ (p.1, p.2), z)) =ᶠ[nhds 0] fun z => μ (p.1, μ (p.2, z))

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal) {E : Type u_1} [inst_1 : NormedAddCommGroup E]
  [NormedSpace ℝ E] [ChartedSpace E M.carrier], IsOpen ↑(Subgroup.connectedComponentOfOne M.carrier)

∀ {G : Type u} [inst : Group G] {T : Set G} {Internal : Set G → Prop}
  (M : DirectedCycles.InternalLocallyCompactGroupModel G T Internal) (S : Subgroup M.carrier) (hS : IsOpen ↑S)
  (x : ↥(Subgroup.comap M.map S)), ↑((DirectedCycles.openSubgroupGoodModel M S hS).map x) = M.map ↑x

∀ {G : Type u_1} {H : Type u_2} [inst : Group G] [inst_1 : Group H] (f : G →* H) (hf : Function.Surjective ⇑f) {r c : ℕ}
  (Q : DirectedCycles.CosetNilprogression H r c),
  (DirectedCycles.preimageCosetNilprogression f hf Q).carrier = ⇑f ⁻¹' Q.carrier

∀ {G : Type u_1} [inst : Group G] [Fintype G] {K : ℕ} {A : Finset G},
  DirectedCycles.IsStrongFiniteApproximateGroup K A →
    ∃ H,
      ∃ (hH : H.Normal),
        let U := Subgroup.closure ↑A;
        have B := ⇑U.subtype ⁻¹' ↑A;
        have q := QuotientGroup.mk' H;
        IsApproximateSubgroup (↑K) (⇑q '' B) ∧ ∀ (y : ↥U ⧸ H), (∀ (n : ℕ), y ^ n ∈ ⇑q '' B) → y = 1

∀ {G : Type u_1} [inst : Group G] [Fintype G] {K : ℕ} {A : Finset G},
  DirectedCycles.IsStrongFiniteApproximateGroup K A →
    ∃ H,
      ∃ (hH : H.Normal),
        let U := Subgroup.closure ↑A;
        have B := ⇑U.subtype ⁻¹' ↑A;
        have q := QuotientGroup.mk' H;
        ↑H ⊆ B ∧ IsApproximateSubgroup (↑K) (⇑q '' B) ∧ ∀ (y : ↥U ⧸ H), (∀ (n : ℕ), y ^ n ∈ ⇑q '' B) → y = 1

∀ {ι : Type u_1} (U : Ultrafilter ι) (G : ι → Type u_2) (L : (i : ι) → DirectedCycles.LocalGroupAlgebra (G i))
  [(i : ι) → Fintype (G i)] (A : (i : ι) → Finset (G i)) {K : ℕ} (hd : ∀ᶠ (i : ι) in ↑U, (L i).DivisionClosed)
  (hr : ∀ᶠ (i : ι) in ↑U, (L i).Reversible),
  (∀ᶠ (i : ι) in ↑U, DirectedCycles.IsStrongLocalFiniteApproximateGroup (L i) K (A i)) →
    let M := DirectedCycles.localUltraAlgebra (↑U) G L;
    have B := DirectedCycles.localUltraSet (↑U) G fun i => ↑(A i);
    have H := {x | M.escapeNorm B x = 0};
    have hD := ⋯;
    have hR := ⋯;
    ∃ (W : M.NormalSubgroupWindow H (M.setMul H B)), (W.congruence hD ⋯).algebra.IsNSS Set.univ

∀ {G : Type u_1} {V : Type u_2} [inst : Group G] [inst_1 : MulAction G V] {D E : DirectedCycles.Digraph V}
  (hE : ∀ (g : G) (x y : V), E (g • x) (g • y) ↔ E x y) (base : (x y : V) → E x y → DirectedCycles.SimplePath D x y)
  (x y : V) (hxy : E x y) (g : G), (DirectedCycles.twistedRoute hE base x y hxy g).head? = some x

∀ {G : Type u_1} {V : Type u_2} [inst : Group G] [inst_1 : MulAction G V] {D E : DirectedCycles.Digraph V}
  (hE : ∀ (g : G) (x y : V), E (g • x) (g • y) ↔ E x y) (base : (x y : V) → E x y → DirectedCycles.SimplePath D x y)
  (x y : V) (hxy : E x y) (g : G), (DirectedCycles.twistedRoute hE base x y hxy g).getLast? = some y

∀ {G : Type u_1} {V : Type u_2} [inst : Group G] [inst_1 : MulAction G V] {D E : DirectedCycles.Digraph V}
  (hE : ∀ (g : G) (x y : V), E (g • x) (g • y) ↔ E x y) (base : (x y : V) → E x y → DirectedCycles.SimplePath D x y)
  (x y : V) (hxy : E x y) (g : G), (DirectedCycles.twistedRoute hE base x y hxy g).Nodup

∀ {G : Type u_1} {V : Type u_2} [inst : Group G] [inst_1 : MulAction G V] {D : DirectedCycles.Digraph V} {a : G}
  (self : DirectedCycles.ActionOrbitCycleWalk G D a) (i : Fin self.length),
  D (self.point i.castSucc) (self.point i.succ)

∀ {ι : Type u_1} {G : ι → Type u_2} [inst : (i : ι) → Group (G i)] {A : (i : ι) → Finset (G i)}
  (self : DirectedCycles.ApproximateRootChain G A) (n : ℕ) (i : ι),
  IsApproximateSubgroup (self.bound n) ↑(self.roots n i)

∀ {G : ℕ → Type u_1} [inst : (i : ℕ) → Group (G i)] {A : (i : ℕ) → Finset (G i)}
  (C : DirectedCycles.ApproximateRootChain G A) (u : Ultrafilter ℕ),
  ↑u ≤ Filter.atTop →
    ∀ (K : ℝ) (hA : ∀ (i : ℕ), IsApproximateSubgroup K ↑(A i)),
      let B := DirectedCycles.ultraSet (↑u) G fun i => ↑(A i);
      let H := Subgroup.closure B;
      IsCompact (⇑H.subtype ⁻¹' B ^ 4)

∀ {ι : Type u_1} {G : ι → Type u_2} [inst : (i : ι) → Group (G i)] {A : (i : ι) → Finset (G i)}
  (self : DirectedCycles.ApproximateRootChain G A) (n : ℕ) (i : ι),
  ∀ x ∈ ↑(A i) ^ 4, ∀ g ∈ ↑(self.roots (n + 1) i) ^ 8, x⁻¹ * g * x ∈ ↑(self.roots n i) ^ 4

∀ {ι : Type u_1} {G : ι → Type u_2} [inst : (i : ι) → Group (G i)] {A : (i : ι) → Finset (G i)}
  (self : DirectedCycles.ApproximateRootChain G A) (n : ℕ) (i : ι),
  self.density n * ↑(A i).card ≤ ↑(self.roots n i).card

∀ {G : ℕ → Type u_1} [inst : (i : ℕ) → Group (G i)] {A : (i : ℕ) → Finset (G i)}
  (C : DirectedCycles.ApproximateRootChain G A) (u : Ultrafilter ℕ),
  ↑u ≤ Filter.atTop →
    ∀ (K : ℝ) (hA : ∀ (i : ℕ), IsApproximateSubgroup K ↑(A i)),
      let B := DirectedCycles.ultraSet (↑u) G fun i => ↑(A i);
      let H := Subgroup.closure B;
      LocallyCompactSpace ↥H

∀ {ι : Type u_1} {G : ι → Type u_2} [inst : (i : ι) → Group (G i)] {A : (i : ι) → Finset (G i)}
  (C : DirectedCycles.ApproximateRootChain G A) (f : Filter ι) (hAone : ∀ (i : ι), 1 ∈ A i) (n : ℕ),
  (C.shrinking f hAone).sets n ⊆ (DirectedCycles.ultraSet f G fun i => ↑(A i)) ^ 4

∀ {G : Type u_1} [inst : Group G] [inst_1 : Finite G] {a : G} {S : Set G} {D : ℕ}
  (input : DirectedCycles.ChosenLiftInput a S D),
  2 ≤ (DirectedCycles.slotBaseline (DirectedCycles.cyclicLiftSlots a D input.data)).length

∀ {G : Type u} [inst : Group G] [inst_1 : TopologicalSpace G] {U : Set G}
  (self : DirectedCycles.CompactNSSSubquotientData G U),
  let this := ⋯;
  DirectedCycles.HasNoSmallSubgroups (↥self.source ⧸ self.kernel)

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin E.length),
  List.IsChain E.allowedStep (DirectedCycles.wordVertices (E.vertex e) (E.edgeWord e))

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (self : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin self.length),
  self.level e = l (self.position e) → self.level ((finRotate self.length) e) = 0

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (S : Set G),
  a ∈ S → (∀ (e : Fin E.length), E.label e ∈ S) → ∀ (e : Fin E.length), ∀ b ∈ E.edgeWord e, b ∈ S

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin E.length),
  E.vertex e * (E.edgeWord e).prod = E.vertex ((finRotate E.length) e)

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin E.length) (i : Fin (E.edgeWord e).length),
  (E.edgeWord e)[↑i] ≠ a → (E.edgeWord e)[↑i] = E.label e

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin E.length) (i : Fin (E.edgeWord e).length),
  (E.edgeWord e)[↑i] ≠ a → E.level e = l (E.position e) ∧ (List.take (↑i) (E.edgeWord e)).prod = a ^ ↑(E.choice e)

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (self : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin self.length),
  self.level e < l (self.position e) → self.vertex ((finRotate self.length) e) = self.vertex e * a

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin E.length),
  List.ofFn (E.point e) = DirectedCycles.wordTails (E.vertex e) (E.edgeWord e)

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin E.length) (k : Fin (E.pointCount e))
  (he : E.level e < l (E.position e)), E.tag e k = ⟨E.position e, DirectedCycles.ExpansionBand.fixed ⟨E.level e, he⟩⟩

∀ {G : Type u_1} {I : Type u_2} [inst : Group G] {a : G} {l : I → ℕ} {D : ℕ}
  (E : DirectedCycles.ExpansionTemplate G I a l D) (e : Fin E.length) (k : Fin (E.pointCount e)),
  (E.tag e k).snd.localIndex = ↑k

∀ {u : Ultrafilter ℕ} {G : ℕ → Type u_1} [inst : (i : ℕ) → Group (G i)] [inst_1 : (i : ℕ) → DecidableEq (G i)]
  {A : (i : ℕ) → Finset (G i)}
  {M :
    let B := DirectedCycles.ultraSet (↑u) G fun i => ↑(A i);
    let H := Subgroup.closure B;
    DirectedCycles.InternalLocallyCompactGroupModel (↥H) (⇑H.subtype ⁻¹' B ^ 4)
      (DirectedCycles.IsInternalFiniteIn u G H)}
  {D : DirectedCycles.LieQuotientData M.carrier M.neighbourhood}
  (self : DirectedCycles.GlobalGoodModelKernelWindows u G A M D) (i : ℕ),
  1 ∈ self.B i ∧ (∀ x ∈ self.B i, x⁻¹ ∈ self.B i) ∧ self.B i ⊆ A i ^ 4

∀ {u : Ultrafilter ℕ} {G : ℕ → Type u_1} [inst : (i : ℕ) → Group (G i)] [inst_1 : (i : ℕ) → DecidableEq (G i)]
  {A : (i : ℕ) → Finset (G i)}
  {M :
    let B := DirectedCycles.ultraSet (↑u) G fun i => ↑(A i);
    let H := Subgroup.closure B;
    DirectedCycles.InternalLocallyCompactGroupModel (↥H) (⇑H.subtype ⁻¹' B ^ 4)
      (DirectedCycles.IsInternalFiniteIn u G H)}
  {D : DirectedCycles.LieQuotientData M.carrier M.neighbourhood}
  (self : DirectedCycles.GlobalGoodModelKernelWindows u G A M D),
  ⇑M.map ⁻¹' closure self.inner ⊆
    ⇑(Subgroup.closure (DirectedCycles.ultraSet (↑u) G fun i => ↑(A i))).subtype ⁻¹'
      DirectedCycles.ultraSet (↑u) G fun i => ↑(self.B i)

∀ {u : Ultrafilter ℕ} {G : ℕ → Type u_1} [inst : (i : ℕ) → Group (G i)] [inst_1 : (i : ℕ) → DecidableEq (G i)]
  {A : (i : ℕ) → Finset (G i)}
  {M :
    let B := DirectedCycles.ultraSet (↑u) G fun i => ↑(A i);
    let H := Subgroup.closure B;
    DirectedCycles.InternalLocallyCompactGroupModel (↥H) (⇑H.subtype ⁻¹' B ^ 4)
      (DirectedCycles.IsInternalFiniteIn u G H)}
  {D : DirectedCycles.LieQuotientData M.carrier M.neighbourhood}
  (self : DirectedCycles.GlobalGoodModelKernelWindows u G A M D),
  (⇑(Subgroup.closure (DirectedCycles.ultraSet (↑u) G fun i => ↑(A i))).subtype ⁻¹'
      DirectedCycles.ultraSet (↑u) G fun i => ↑(self.B i)) ⊆
    ⇑M.map ⁻¹' self.outer

∀ {u : Ultrafilter ℕ} {G : ℕ → Type u_1} [inst : (i : ℕ) → Group (G i)] [inst_1 : (i : ℕ) → DecidableEq (G i)]
  {A : (i : ℕ) → Finset (G i)}
  {M :
    let B := DirectedCycles.ultraSet (↑u) G fun i => ↑(A i);
    let H := Subgroup.closure B;
    DirectedCycles.InternalLocallyCompactGroupModel (↥H) (⇑H.subtype ⁻¹' B ^ 4)
      (DirectedCycles.IsInternalFiniteIn u G H)}
  {D : DirectedCycles.LieQuotientData M.carrier M.neighbourhood}
  (self : DirectedCycles.GlobalGoodModelKernelWindows u G A M D) (i : ℕ),
  1 ∈ self.W i ∧ (∀ x ∈ self.W i, x⁻¹ ∈ self.W i) ∧ self.W i ⊆ A i ^ 4

∀ {u : Ultrafilter ℕ} {G : ℕ → Type u_1} [inst : (i : ℕ) → Group (G i)] [inst_1 : (i : ℕ) → DecidableEq (G i)]
  {A : (i : ℕ) → Finset (G i)}
  {M :
    let B := DirectedCycles.ultraSet (↑u) G fun i => ↑(A i);
    let H := Subgroup.closure B;
    DirectedCycles.InternalLocallyCompactGroupModel (↥H) (⇑H.subtype ⁻¹' B ^ 4)
      (DirectedCycles.IsInternalFiniteIn u G H)}
  {D : DirectedCycles.LieQuotientData M.carrier M.neighbourhood}
  (self : DirectedCycles.GlobalGoodModelKernelWindows u G A M D),
