∀ {G : Type u_1} {L : DirectedCycles.LocalGroupAlgebra G} {S : Set G} {Rel : G → G → Prop} {refl : ∀ x ∈ S, Rel x x}
  {symm : ∀ x ∈ S, ∀ y ∈ S, Rel x y → Rel y x} {trans : ∀ x ∈ S, ∀ y ∈ S, ∀ z ∈ S, Rel x y → Rel y z → Rel x z}
  {inv_rel : ∀ x ∈ S, ∀ y ∈ S, Rel x y → Rel (L.inv x) (L.inv y)}
  {mul_rel :
    ∀ a ∈ S,
      ∀ b ∈ S,
        ∀ c ∈ S, ∀ a' ∈ S, ∀ b' ∈ S, ∀ c' ∈ S, L.mulRel a b c → L.mulRel a' b' c' → Rel a a' → Rel b b' → Rel c c'}
  {Rel_1 : G → G → Prop} {refl_1 : ∀ x ∈ S, Rel_1 x x} {symm_1 : ∀ x ∈ S, ∀ y ∈ S, Rel_1 x y → Rel_1 y x}
  {trans_1 : ∀ x ∈ S, ∀ y ∈ S, ∀ z ∈ S, Rel_1 x y → Rel_1 y z → Rel_1 x z}
  {inv_rel_1 : ∀ x ∈ S, ∀ y ∈ S, Rel_1 x y → Rel_1 (L.inv x) (L.inv y)}
  {mul_rel_1 :
    ∀ a ∈ S,
      ∀ b ∈ S,
        ∀ c ∈ S,
          ∀ a' ∈ S, ∀ b' ∈ S, ∀ c' ∈ S, L.mulRel a b c → L.mulRel a' b' c' → Rel_1 a a' → Rel_1 b b' → Rel_1 c c'},
  { Rel := Rel, refl := refl, symm := symm, trans := trans, inv_rel := inv_rel, mul_rel := mul_rel } =
      { Rel := Rel_1, refl := refl_1, symm := symm_1, trans := trans_1, inv_rel := inv_rel_1, mul_rel := mul_rel_1 } →
    Rel = Rel_1

∀ {G : Type u_2} {H : Type u_1} {L : DirectedCycles.LocalGroupAlgebra G} {T : DirectedCycles.LocalGroupAlgebra H}
  {u : G} {N : ℕ} (p : L.PowerSegment u N) (f : DirectedCycles.LocalGroupHom L T),
  ∀ n ≤ N, T.Product (List.replicate n (f.toFun u)) (f.toFun (p.power n))

∀ {G : Type u_1} {L : DirectedCycles.LocalGroupAlgebra G} {g : G} {N : ℕ} (power power_1 : ℕ → G)
  (e_power : power = power_1) (product : ∀ n ≤ N, L.Product (List.replicate n g) (power n)),
  { power := power, product := product } = { power := power_1, product := ⋯ }

∀ {G : Type u_1} {L : DirectedCycles.LocalGroupAlgebra G} {g : G} {N : ℕ} {power : ℕ → G}
  {product : ∀ n ≤ N, L.Product (List.replicate n g) (power n)} {power_1 : ℕ → G}
  {product_1 : ∀ n ≤ N, L.Product (List.replicate n g) (power_1 n)},
  { power := power, product := product } = { power := power_1, product := product_1 } → power = power_1

∀ {G : Type u_1} (L : DirectedCycles.LocalGroupAlgebra G) {u : G} {N : ℕ} (p : ℕ → G) (h0 : p 0 = L.one)
  (h1 : 1 ≤ N → p 1 = u) (hadd : ∀ (n m : ℕ), n + m ≤ N → L.mulRel (p n) (p m) (p (n + m))),
  DirectedCycles.LocalGroupAlgebra.PowerSegment.of_add L p h0 h1 hadd = { power := p, product := ⋯ }

∀ {G : Type u_1} {L : DirectedCycles.LocalGroupAlgebra G} {g : G} {power : ℕ → G}
  {product : ∀ (n : ℕ), L.Product (List.replicate n g) (power n)} {power_1 : ℕ → G}
  {product_1 : ∀ (n : ℕ), L.Product (List.replicate n g) (power_1 n)},
  { power := power, product := product } = { power := power_1, product := product_1 } → power = power_1

∀ {G : Type u_1} [inst : Group G] (S : Set G) (h1 : 1 ∈ S) (hi : ∀ x ∈ S, x⁻¹ ∈ S) {A : Set ↑S} {r c : ℕ}
  (W : ((DirectedCycles.LocalGroupAlgebra.ofGroup G).restrict S h1 hi).ProgressionWitness A r c) (i : Fin r),
  1 ≤ W.lengths i

∀ {G : Type u_1} [inst : Group G] (S : Set G) (h1 : 1 ∈ S) (hi : ∀ x ∈ S, x⁻¹ ∈ S) {A : Set ↑S} {r c : ℕ}
  (W : ((DirectedCycles.LocalGroupAlgebra.ofGroup G).restrict S h1 hi).ProgressionWitness A r c),
  Function.Injective ((DirectedCycles.LocalGroupAlgebra.ofGroup G).orderedGrid ⋯)

∀ {G : Type u_1} {L : DirectedCycles.LocalGroupAlgebra G} {A : Set G} {r c : ℕ} {generators : Fin r → G}
  {lengths : Fin r → ℕ} {lengths_pos : ∀ (i : Fin r), 1 ≤ lengths i} {words : L.SignedWordsIn generators lengths A}
  {proper : Function.Injective (L.orderedGrid words)}
  {commutators : ∀ (x : G), L.GeneratorCommutators (Set.range generators) c x → x = L.one} {generators_1 : Fin r → G}
  {lengths_1 : Fin r → ℕ} {lengths_pos_1 : ∀ (i : Fin r), 1 ≤ lengths_1 i}
  {words_1 : L.SignedWordsIn generators_1 lengths_1 A} {proper_1 : Function.Injective (L.orderedGrid words_1)}
  {commutators_1 : ∀ (x : G), L.GeneratorCommutators (Set.range generators_1) c x → x = L.one},
  { generators := generators, lengths := lengths, lengths_pos := lengths_pos, words := words, proper := proper,
        commutators := commutators } =
      { generators := generators_1, lengths := lengths_1, lengths_pos := lengths_pos_1, words := words_1,
        proper := proper_1, commutators := commutators_1 } →
    generators = generators_1 ∧ lengths = lengths_1
